#pragma once

#include <optional>

#include "irmv/application/initialization.hpp"
#include "irmv/application/input_router.hpp"
#include "irmv/application/locomotion_source.hpp"
#include "irmv/application/robot_client.hpp"
#include "irmv/configuration/application_config.hpp"
#include "irmv/protocol/types.hpp"

namespace irmv::application {

// The seven behaviours of the upper layer. `Ready` exists on its own so
// "still interpolating" and "a behaviour may be started" are observable, and it
// keeps being generated by the upper layer: once the upper process is gone the
// runtime falls back on its own target deadline instead of holding an old
// gain-carrying target forever. `Locomotion` keeps its enumerator and its entry
// guard, but this phase ships no target generator, so StartLocomotion() never
// enters it.
enum class BehaviorState {
  Starting,
  Standby,
  Damping,
  Initializing,
  Ready,
  Locomotion,
  Fault,
};

// What the behaviour FSM latched, and only that: the application-local cause of
// a Fault, kept separately from the runtime's own FaultReason (which the lower
// layer reports about itself and which the FSM never latches on the runtime's
// behalf). The latch is cleared only by a confirmed Reset.
//
// A lost input device is not one of these: the loop turns it into the same
// RequestExit an exit key raises, so the behaviour leaves through the bounded
// exit path and reports what it could not prove.
enum class FaultCause {
  None = 0,
  OperatorEmergencyStop,
  RuntimeFault,
  RuntimeUnreachable,
  RuntimeRestarted,
  InitializationFailed,
  RequestTimeout,
  UnexpectedContext,
  // The local policy source did not produce a usable result inside the
  // configured deadline: a failed inference, a late one, or a first frame that
  // was never confirmed. The behaviour stops generating and asks for damping;
  // the frames a stale result would have produced are never published.
  LocalPolicyFailed,
};

// What one Step decided, and everything the loop displays. It carries no DDS
// type and no runtime type: the loop sends `command` through
// RobotClient::SendCommand, publishes a heartbeat when asked, and prints the
// rest.
struct BehaviorStep {
  // The behaviour after this iteration.
  BehaviorState state{BehaviorState::Starting};
  // The latched application-local cause; None while the FSM is not latched.
  FaultCause fault_cause{FaultCause::None};
  // The lower layer's own facts, as the last trustworthy state reported them.
  protocol::FaultReason runtime_fault_reason{protocol::FaultReason::None};
  protocol::StopReason runtime_stop_reason{protocol::StopReason::None};
  // False when no current state is known: the loop must display Unknown and
  // must not report the last remembered one as the runtime's present fact.
  bool runtime_state_known{false};
  protocol::ExecutionState runtime_state{protocol::ExecutionState::Boot};
  protocol::OutputAction runtime_output{protocol::OutputAction::ZeroTorque};
  // The reason of the last rejected request, kept for display.
  protocol::RejectReason last_reject_reason{protocol::RejectReason::None};
  // The initialization plan was refused by admission (the runtime would not
  // accept it): the FSM stayed in Damping, sent nothing and latched nothing.
  // Set for the step that decided it only.
  bool initialization_refused{false};
  // One target frame to send this iteration; `command` is complete except for
  // the routing identity RobotClient fills in (instance, session, send stamp).
  bool send_command{false};
  protocol::JointCommand command{};
  // A supervision heartbeat is due this iteration.
  bool send_heartbeat{false};
  // The exit sequence finished: the process may leave now.
  bool exit_ready{false};
  // True while the operator has asked for the locomotion behaviour and no stop,
  // fault or exit has cancelled it. The supervision loop submits observations
  // and offers frames exactly while this holds, so the two layers cannot
  // disagree about whether a source is wanted.
  bool locomotion_armed{false};
  // ... and the damping stop was confirmed by a fresh lower state. False means
  // the stop was never proven, which the loop must report as Unknown (or as the
  // runtime's own fault), never as "damped".
  bool exit_stop_confirmed{false};
};

// The behaviour FSM and the serial supervision order of one iteration.
//
// It is a pure function of the view it is handed and of the times it is given:
// it reads no clock, allocates nothing, never throws, and touches no transport,
// no DDS type and no thread. The loop polls the client once, passes the view
// in, and then only sends what the Step returned and prints what it reported.
//
// The iteration is serial, in this order, and the order is the safety rule:
//
//   1. the fresh lower state and every fault it proves (latched, with the stop
//      a fault owes the machine);
//   2. the emergency stop and the exit, which do not wait for a confirmation;
//   3. the outcome of the pending request, then the ordinary requests and the
//      initialization targets;
//   4. last, and only after the checks above, the heartbeat decision.
//
// Every transition is gated on a matching confirmation: an Applied result the
// client accepted *and* a later fresh state that shows the target behaviour.
// The FSM never claims a motor executed anything, and never claims a stop that
// was not confirmed.
class BehaviorFsm {
 public:
  // `config` and `client` must outlive the FSM. `source` is the locomotion
  // source of this process run, fixed for its whole life: it decides whether
  // the frames of an authorized context are published by this behaviour (a
  // local model, whose frames this process relays) or by the source itself (an
  // external producer, which publishes on the execution topic under the
  // producer identity the runtime granted).
  BehaviorFsm(const configuration::ApplicationConfig &config,
              RobotClient &client,
              LocomotionSource source = LocomotionSource::None);

  BehaviorFsm(const BehaviorFsm &) = delete;
  BehaviorFsm &operator=(const BehaviorFsm &) = delete;

  // One iteration: `now_us` is the host monotonic instant, `event` the semantic
  // input event of this iteration (None when there is none) and `view` the
  // ClientView of the Poll this iteration already made. Step never polls.
  //
  // The loop hands one Poll view to several Steps of the same iteration - one
  // per input event, then a final one with None - and Step is idempotent: the
  // edge-triggered outcome of the view is consumed once per new `poll_seq` (the
  // first Step that sees that serial acts on it, every later Step on the same
  // view sees None), and a stop an earlier Step of the iteration began is
  // visible to the later ones.
  BehaviorStep Step(protocol::TimeUs now_us, InputEvent event,
                    const ClientView &view);

  BehaviorState state() const { return state_; }
  FaultCause fault_cause() const { return fault_cause_; }

  // Offers the newest frame the local policy produced while the source is not
  // authorized yet. The behaviour keeps the freshest one and uses it as the
  // first frame of the Tracking request it proposes when the operator asks for
  // the locomotion behaviour; nothing of it is published before that request is
  // confirmed.
  void OfferLocomotionCandidate(const protocol::JointCommand &frame,
                                protocol::TimeUs now_us);

  // Offers the newest frame of an authorized locomotion source. The behaviour
  // publishes the freshest one at the target cadence while it is in Locomotion,
  // and refuses to publish a frame that belongs to another producer or epoch
  // than the one it authorized.
  void OfferLocomotionTarget(const protocol::JointCommand &frame,
                             protocol::TimeUs now_us);

  // The supervision loop could not obtain a usable local policy result inside
  // the configured deadline. It is the same latch as any other upper fault: the
  // generation stops, the candidate is dropped and the machine is asked to
  // damp.
  void LatchLocalPolicyFault(protocol::TimeUs now_us);

  // The producer and the epoch of the locomotion authorization this behaviour
  // holds - the pending one included - or kNoId and zero while it holds none.
  // The supervision loop stamps the frames it builds with them, so a frame that
  // belongs to a withdrawn authorization is refused by the check EmitTarget
  // applies rather than published under the current one.
  protocol::Id locomotion_producer() const;
  protocol::Sequence locomotion_epoch() const;

  // The command sequence stamped on the first frame of the locomotion request
  // this behaviour proposed: the point the runtime adopted as the start of the
  // authorized stream. Zero while it holds no locomotion authorization. The
  // supervision loop reports it to an external producer, which continues the
  // stream from the next number - a producer that restarted its own numbering
  // would publish a frame the runtime's command gate refuses.
  protocol::Sequence locomotion_first_command_seq() const;

  // Starts the exit sequence: stop generating, cancel the pending request, ask
  // for Damping and wait for its confirmation for at most
  // supervision.request_deadline_us. The request itself leaves on the next
  // Step, which is the first call that can see whether the runtime is already
  // in Fault and must then keep its own output rule instead. Called by the exit
  // key, a signal and a lost input device.
  void RequestExit(protocol::TimeUs now_us);

 private:
  // What the one request the FSM may have outstanding is, and therefore what
  // its confirmation does to the behaviour.
  enum class Pending {
    None,
    Acquire,
    Damping,
    ZeroTorque,
    Tracking,
    Reset,
  };

  // What one confirmed request did to the behaviour.
  enum class Confirmation {
    // The kind has no state requirement of its own.
    NotApplicable,
    // The transition was taken, or the state contradicts it for good.
    Applied,
    // The state has not witnessed the behaviour yet: the confirmation waits for
    // one instead of being dropped by a Step that happened to poll first.
    Deferred,
  };

  void FreshStateAndFaults(protocol::TimeUs now_us, const ClientView &view);
  void EmergencyStop(protocol::TimeUs now_us, const ClientView &view);
  // `outcome` is the request outcome this Step may act on: the view's own
  // outcome while this Step is the first to see that poll, and None otherwise.
  void ExitStep(protocol::TimeUs now_us, const ClientView &view,
                RequestOutcome outcome);
  void ConsumeOutcome(protocol::TimeUs now_us, const ClientView &view,
                      RequestOutcome outcome);
  // What one confirmed request does to the behaviour. It is one decision for
  // every kind, so a confirmation can be taken now and, when the state has not
  // witnessed it yet, held instead of dropped.
  Confirmation ApplyConfirmation(Pending pending,
                                 const protocol::RobotState &state);
  void HoldConfirmation(Pending pending, protocol::TimeUs now_us);
  // Applies a held confirmation as soon as a fresh state witnesses it, and
  // drops it on its own deadline, on a new request, on a latch and on the exit.
  void ApplyHeldConfirmation(protocol::TimeUs now_us, const ClientView &view);
  void DropHeldConfirmation();
  // Handles the ordinary requests and the initialization targets of this
  // event. Whether a stop was begun here is not reported: the target generator
  // is gated on StopInFlight(), the durable fact that survives the whole
  // pending window and the later Steps of this same iteration.
  void OrdinaryRequests(protocol::TimeUs now_us, InputEvent event,
                        const ClientView &view, BehaviorStep *out);
  void TryStartInitialization(protocol::TimeUs now_us, const ClientView &view,
                              BehaviorStep *out);
  void TryReset(protocol::TimeUs now_us, const ClientView &view);
  void EmitTarget(protocol::TimeUs now_us, const ClientView &view,
                  BehaviorStep *out);
  // Proposes the locomotion authorization when the operator asked for it, the
  // behaviour is Ready, the link is fresh and a first frame is still fresh.
  void TryStartLocomotion(protocol::TimeUs now_us, const ClientView &view);
  // Drops the pending first frame, the published target and the sequence of the
  // locomotion source. Every stop, fault and exit calls it: nothing of a
  // withdrawn authorization may be published afterwards.
  void CancelLocomotion();

  // Latches `cause` (the first cause wins) and, when the fault owes the machine
  // a stop, asks for Damping unless a stop of ours is already on the wire.
  void LatchFault(FaultCause cause, protocol::TimeUs now_us, bool request_stop);
  bool BeginDampingStop(protocol::TimeUs now_us);
  bool BeginZeroTorqueStop(protocol::TimeUs now_us);
  bool BeginStop(protocol::Operation operation, Pending kind,
                 protocol::TimeUs now_us);
  bool BeginAcquire(protocol::TimeUs now_us);
  bool AcquireNeeded(protocol::TimeUs now_us, const ClientView &view) const;
  void CancelInitialization();
  bool StopPending() const;
  // True while a stop this FSM began is still unresolved: the client holds it
  // and the operation last begun is one of the transport's stop-lane
  // operations. Only a durable stop suppresses target generation, not the fact
  // that a stop was begun in this very Step.
  bool StopInFlight() const;
  // Whether a Tracking state is the context this FSM authorized: the confirmed
  // initialization/hold context, the context the pending Tracking request
  // proposes, or the context that was confirmed until that request was
  // proposed.
  bool ExpectedTracking(const protocol::RobotState &state) const;
  // Remembers the confirmed context before a Tracking request replaces it, and
  // forgets it once nothing may publish it any more.
  void RememberConfirmedTracking();
  void DropPreviousTracking();
  bool TargetDue(protocol::TimeUs now_us) const;
  bool HeartbeatDue(protocol::TimeUs now_us) const;

  const configuration::ApplicationConfig &config_;
  RobotClient &client_;
  // The producer the initialization trajectory and the Ready hold are published
  // under, fixed at construction.
  protocol::Id producer_id_{};

  // The locomotion source of this run, fixed for its whole life: it decides
  // whether this behaviour publishes the frames of an authorized context or
  // leaves that to the source itself (see the constructor).
  const LocomotionSource locomotion_source_;
  // How long the first frame of that source stays usable as the frame of a
  // request: a frame of a revoked source must not turn into an authorization.
  // The local model's own deadline and an external producer's preparation
  // deadline are different promises, so the value follows the source.
  const protocol::TimeUs locomotion_candidate_ttl_us_;

  // The initialization trajectory and the Ready hold, owned by value. The
  // generator latches its own progress and offers no cancel (Start refuses
  // while a move is in flight), so cancelling - which an ordinary stop, a
  // ZeroTorque stop, a fault and the exit all do - rebuilds it in place: the
  // optional is that storage and never allocates.
  std::optional<Initialization> initialization_;

  BehaviorState state_{BehaviorState::Starting};
  FaultCause fault_cause_{FaultCause::None};
  protocol::RejectReason last_reject_reason_{protocol::RejectReason::None};
  // The runtime's latched fault identity, kept for the explicit Reset; 0 while
  // no lower fault was observed.
  protocol::Sequence lower_fault_id_{0};

  Pending pending_{Pending::None};
  protocol::Id pending_producer_{};
  protocol::Sequence pending_epoch_{0};
  // A confirmation whose behaviour the state had not witnessed yet when it was
  // read, and the instant it stops waiting for one.
  Pending held_{Pending::None};
  protocol::TimeUs held_deadline_us_{0};

  // The confirmed Tracking context the upper behaviour relies on.
  bool tracking_active_{false};
  protocol::Id tracking_producer_{};
  protocol::Sequence tracking_epoch_{0};

  // The context that was confirmed until this FSM proposed the Tracking request
  // now pending. The runtime keeps publishing it until it applies that request,
  // so a state of it that crossed the request on the wire must not be read as an
  // authorization nobody asked for: without this memory, asking for a new
  // context while the initialization hold is still the newest thing the runtime
  // published - which is what both locomotion sources do - faults the behaviour
  // on a perfectly legal transition. It is dropped by every path that withdraws
  // the context (a stop, a latch, the exit, the runtime leaving tracking) and by
  // the confirmation of the request that replaced it.
  bool have_previous_tracking_{false};
  protocol::Id previous_tracking_producer_{};
  protocol::Sequence previous_tracking_epoch_{0};

  // A state has been observed at least once; before that, Starting waits
  // instead of calling an absent link unreachable.
  bool saw_state_{false};
  // The highest serial of a poll whose outcome this FSM already consumed. The
  // loop hands one view to several Steps (one per input event) and the outcome
  // is edge triggered: without this a second Step would apply the same answer
  // to a request it began in the first one. It is a monotonic watermark, so
  // re-presenting an older view after a newer poll was seen does not re-enable
  // that older outcome - and a hand-built ClientView with the default
  // poll_seq of 0 is treated as already consumed.
  protocol::Sequence consumed_poll_seq_{0};
  // The operation of the request the FSM began last, so a repeated key can tell
  // "the same stop is already on the wire" from "a different stop preempts".
  protocol::Operation pending_operation_{protocol::Operation::AcquireSession};
  // The last handover attempt, so a refused session is retried on the request
  // retry cadence instead of on every iteration.
  bool have_acquire_{false};
  protocol::TimeUs last_acquire_us_{0};
  bool have_target_{false};
  protocol::TimeUs last_target_us_{0};
  bool have_heartbeat_{false};
  protocol::TimeUs last_heartbeat_us_{0};

  // The local policy source: the freshest frame produced before the request,
  // the freshest frame of the authorized source and the sequence this behaviour
  // stamps on each frame it publishes.
  bool have_locomotion_candidate_{false};
  protocol::JointCommand locomotion_candidate_{};
  protocol::TimeUs locomotion_candidate_us_{0};
  bool have_locomotion_target_{false};
  protocol::JointCommand locomotion_target_{};
  protocol::TimeUs locomotion_target_us_{0};
  protocol::Sequence locomotion_seq_{0};
  // The sequence stamped on the first frame of the authorization, kept apart
  // from `locomotion_seq_` because that one keeps counting on every published
  // frame while the start of the stream stays what it was.
  protocol::Sequence locomotion_first_seq_{0};
  // The operator asked for the locomotion behaviour and no stop has cancelled
  // it.
  bool locomotion_armed_{false};
  // The Tracking request on the wire is the locomotion one, so its confirmation
  // enters Locomotion and not Initializing.
  bool pending_locomotion_{false};

  bool exit_requested_{false};
  bool exit_ready_{false};
  bool exit_stop_confirmed_{false};
  protocol::TimeUs exit_deadline_us_{0};
};

}  // namespace irmv::application
